import {matchSession} from './match-session.js';
import {auditEvidence} from './evidence-audit.js';
import {choose} from './studio-insight.js';
const root=document.createElement('section');root.className='truth-quality';root.setAttribute('aria-label','Claim audit and audience comparison');
const host=document.querySelector('#truth .truth-spotlight');if(host)host.after(root);else document.querySelector('#truth .truth-story-grid')?.before(root);
const demoLink=document.createElement('a');demoLink.href='quality-demo.html';demoLink.className='quality-quick-link';demoLink.textContent='90-second evidence story ↗';document.querySelector('.truth-demo-entry')?.append(demoLink);
function render(s){const t=(a,b,c)=>choose(s.language,a,b,c),snapshot={scenario:s.scenario,time:s.time,corrected:s.corrected,tracking:true,language:s.language},a=auditEvidence(snapshot);
 const wasOpen=root.querySelector('details')?.open;root.replaceChildren();const title=document.createElement('h2');title.textContent=t('What changes. What survives.','Qué cambia. Qué se conserva.','O que muda. O que permanece.');root.append(title);
 const grid=document.createElement('div');grid.className='quality-ledger';for(const row of a.ledger){const card=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p');h.textContent={withdrawn:t('Withdrawn / limited','Retirado / limitado','Retirado / limitado'),preserved:t('Preserved','Conservado','Preservado'),uncertain:t('Still uncertain','Aún incierto','Ainda incerto')}[row.kind];p.textContent=row.text;card.dataset.kind=row.kind;card.append(h,p);grid.append(card);}root.append(grid);
 const compare=document.createElement('details'),summary=document.createElement('summary');summary.textContent=t('Same evidence. Beginner vs analyst.','Misma evidencia. Principiante y analista.','Mesma evidência. Iniciante e analista.');compare.open=!!wasOpen;compare.append(summary);for(const[id,label]of [['beginner',t('New to football','Nuevo en el fútbol','Novo no futebol')],['analyst',t('Tactical analyst','Analista táctico','Analista tático')]]){const article=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=label;p.textContent=a.audiences[id];article.append(h,p);compare.append(article);}root.append(compare);
 const actions=document.createElement('div');actions.className='quality-actions';const b=document.createElement('button');b.className='outline-button';b.textContent=t('Challenge the crew with this evidence ↗','Cuestionar al equipo con esta evidencia ↗','Questionar a equipe com esta evidência ↗');b.onclick=()=>window.dispatchEvent(new CustomEvent('btr-show-why',{detail:{...snapshot,reviewIntent:'challenge',tab:'story'}}));actions.append(b);for(const[href,text]of [['quality-demo.html',t('90-second evidence demo ↗','Demo de evidencia de 90 segundos ↗','Demo de evidência de 90 segundos ↗')],['quality-proof.html',t('Read the measured comparison ↗','Leer la comparación medida ↗','Ler a comparação medida ↗')]]){const link=document.createElement('a');link.href=href;link.textContent=text;actions.append(link);}root.append(actions);
}
// Re-render only the active page; replay ticks must not continually replace controls.
let last='';matchSession.subscribe(s=>{const key=JSON.stringify([s.scenario,Math.floor(s.time),s.corrected,s.language]);if(s.section==='truth'&&last!==key&&!root.contains(document.activeElement)){last=key;render(s);}});render(matchSession.get());
